// marked.js — implementación local para Sistema Jhomeron
// Sin dependencia de CDN externo
(function(global) {
    var marked = {
        parse: function(src) {
            if (!src) return '';
            src = src.replace(/\r\n|\r/g, '\n');

            // Headers H1-H6
            src = src.replace(/^(#{1,6})\s+(.+)$/gm, function(m, h, t) {
                var l = h.length;
                var sz = l === 1 ? '1.1em' : l === 2 ? '1em' : '0.95em';
                return '<h' + l + ' style="color:#0d3393;margin:8px 0 4px;font-size:' + sz + '">' + t + '</h' + l + '>';
            });

            // Negrita
            src = src.replace(/\*\*(.+?)\*\*/g, '<strong style="color:#0d3393">$1</strong>');
            src = src.replace(/__(.+?)__/g, '<strong style="color:#0d3393">$1</strong>');

            // Cursiva
            src = src.replace(/\*(.+?)\*/g, '<em>$1</em>');
            src = src.replace(/_(.+?)_/g, '<em>$1</em>');

            // Código inline
            src = src.replace(/`([^`]+)`/g, '<code style="background:#eff6ff;color:#0d3393;padding:2px 5px;border-radius:4px;font-size:0.8rem">$1</code>');

            // Tablas markdown
            src = src.replace(/^\|(.+)\|\s*\n\|[\s\-|:]+\|\s*\n((?:\|.+\|\s*\n?)*)/gm, function(m, header, rows) {
                var ths = header.split('|').filter(function(c) { return c.trim(); })
                    .map(function(c) {
                        return '<th style="background:#eff6ff;color:#0d3393;padding:6px 10px;text-align:left;border-bottom:2px solid #bfdbfe">' + c.trim() + '</th>';
                    }).join('');
                var trs = rows.trim().split('\n').map(function(row) {
                    var tds = row.split('|').filter(function(c) { return c.trim(); })
                        .map(function(c) {
                            return '<td style="padding:5px 10px;border-bottom:1px solid #f1f5f9">' + c.trim() + '</td>';
                        }).join('');
                    return '<tr>' + tds + '</tr>';
                }).join('');
                return '<table style="width:100%;border-collapse:collapse;margin-top:8px;font-size:0.8rem"><thead><tr>' + ths + '</tr></thead><tbody>' + trs + '</tbody></table>';
            });

            // Listas no ordenadas
            src = src.replace(/^[\-\*\+] (.+)$/gm, '<li style="margin-bottom:3px">$1</li>');
            src = src.replace(/(<li[^>]*>[\s\S]*?<\/li>\n?)+/g, function(m) {
                return '<ul style="padding-left:16px;margin:6px 0">' + m + '</ul>';
            });

            // Listas ordenadas
            src = src.replace(/^\d+\.\s+(.+)$/gm, '<li style="margin-bottom:3px">$1</li>');

            // Línea horizontal
            src = src.replace(/^---+$/gm, '<hr style="border:none;border-top:1px solid #e2e8f0;margin:12px 0">');

            // Párrafos y saltos de línea
            src = src.replace(/\n\n/g, '</p><p style="margin:6px 0">');
            src = src.replace(/\n/g, '<br>');

            if (src && !src.startsWith('<')) {
                src = '<p style="margin:6px 0">' + src + '</p>';
            }

            return src;
        }
    };

    // Exportar como global y como módulo
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = marked;
    } else {
        global.marked = marked;
    }
})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : this);